import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.G0y0PQA7.js";const c=JSON.parse('{"title":"기능 설명","description":"","frontmatter":{},"headers":[],"relativePath":"features/index.md","filePath":"features/index.md"}'),l={name:"features/index.md"};function d(o,e,f,s,h,u){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="기능-설명" tabindex="-1">기능 설명 <a class="header-anchor" href="#기능-설명" aria-label="Permalink to &quot;기능 설명&quot;">​</a></h1><p>메뉴와 기능 영역별로 옵션과 동작을 자세히 설명하는 곳입니다. 찾는 기능의 쪽을 골라 필요한 절만 읽으면 됩니다. 할 일을 몇 단계로 따라 하려면 <a href="/relio/quick/start">빠른 시작</a>을 보세요. 앱 안에서는 도움말 › 사용 설명서(<kbd>F1</kbd>)로 짧은 설명을 볼 수 있습니다.</p><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><ul><li><strong>메뉴</strong> — 파일 · 편집 · 보기 · 배치 · 모델 · 도구 · 도움말. <a href="/relio/features/file">파일</a> · <a href="/relio/features/edit">편집</a> · <a href="/relio/features/canvas">캔버스와 팔레트</a> · <a href="/relio/features/model">모델 메뉴</a> · <a href="/relio/features/preferences">환경 설정</a> · <a href="/relio/features/troubleshooting">도움말과 문제 해결</a></li><li><strong>도구 모음</strong> — 새 다이어그램·열기·저장, 삭제·되돌리기·다시 하기, 확대·축소·맞춤·배율, 격자·격자에 맞추기, DB로 내보내기, <strong>맞춤 ▾</strong>, 배경색. <a href="/relio/features/canvas#배치-메뉴">캔버스와 팔레트 › 배치 메뉴</a></li><li><strong>팔레트</strong>(왼쪽) — 그리기 도구. <a href="/relio/features/canvas#팔레트-도구">캔버스와 팔레트 › 팔레트 도구</a></li><li><strong>캔버스</strong> — 다이어그램을 그리는 곳. <a href="/relio/features/canvas">캔버스와 팔레트</a></li><li><strong>아웃라인</strong>(오른쪽 위) — 그룹 컬럼 · 단어 사전 · 테이블 · 뷰 · 트리거 · 시퀀스 · 인덱스 · 테이블스페이스 목록과 개수. <a href="/relio/features/canvas#아웃라인">캔버스와 팔레트 › 아웃라인</a></li><li><strong>축소 미리보기</strong>(오른쪽 아래) — 전체 그림. 보이는 영역 사각형을 끌어 화면을 옮깁니다. <a href="/relio/features/canvas#확대·이동">캔버스와 팔레트 › 확대·이동</a></li><li><strong>카테고리 탭</strong>(아래) — &quot;전체&quot;와 카테고리마다 탭. 줄 오른쪽 끝에 설계 검사의 <strong>문제: …</strong> 단추가 있습니다. <a href="/relio/features/categories">카테고리</a></li><li><strong>문제 목록</strong>(아래 패널) — 설계 검사 지적, 파일을 고친 내역, DDL 경고. <a href="/relio/features/check#문제-목록">설계 검사와 추천</a></li><li><strong>상태 표시줄</strong>(맨 아래) — 왼쪽부터 대상 DB와 버전(누르면 옵션 창), 테이블·컬럼·관계 수, 지금 보는 카테고리(여러 개면 <code>카테고리: 회원 + 주문 · 새 노드 → 주문</code>), 그리고 오른쪽에 Git 브랜치 이름(저장소 안 파일일 때 — 누르면 Git 이력), <strong>컬럼 클릭 금지</strong>(켜져 있을 때 — 누르면 끔), 작업 안내, 선택한 개수, 배율, Relio 버전.</li></ul><p>이 가이드에서 <strong>노드</strong>는 캔버스에 놓이는 상자 — 테이블 · 뷰 · 노트 · 카테고리 영역 · 이미지 — 를 함께 부르는 말입니다. 관계선과 노트 연결선은 <strong>연결선</strong>이라고 부릅니다.</p><h2 id="이럴-땐-여기" tabindex="-1">이럴 땐 여기 <a class="header-anchor" href="#이럴-땐-여기" aria-label="Permalink to &quot;이럴 땐 여기&quot;">​</a></h2><table tabindex="0"><thead><tr><th>하고 싶은 일</th><th>볼 곳</th></tr></thead><tbody><tr><td>SQL·DBML 파일로 새 모델 시작하기</td><td><a href="/relio/quick/import-start">SQL·DBML에서 시작하기</a> · <a href="/relio/features/import">가져오기와 다른 형식</a></td></tr><tr><td>운영 DB 구조를 모델로 가져오기</td><td><a href="/relio/features/database#db에서-가져오기">DB 연동 › DB에서 가져오기</a></td></tr><tr><td>바뀐 것만 DB에 반영하기(ALTER)</td><td><a href="/relio/features/git#변경-sql-만들기">Git과 합치기 › 변경 SQL 만들기</a></td></tr><tr><td>테이블 정의서를 Excel로 만들기</td><td><a href="/relio/features/export#excel">내보내기 › Excel</a></td></tr><tr><td>다른 도구에 붙일 Mermaid·DBML 만들기</td><td><a href="/relio/features/export#글-형식-내보내기-dbml·mermaid·markdown·모델-json">내보내기 › 글 형식 내보내기</a></td></tr><tr><td>등록일·수정자 같은 공통 컬럼 묶기</td><td><a href="/relio/features/model#그룹-관리·글로벌-그룹-관리">모델 메뉴 › 그룹 관리</a></td></tr><tr><td>이름을 한꺼번에 바꾸기</td><td><a href="/relio/features/edit#검색-창">편집 › 검색 창</a></td></tr><tr><td>여러 테이블의 컬럼 속성을 한 표에서 고치기</td><td><a href="/relio/features/edit#모든-속성-편집">편집 › 모든 속성 편집</a></td></tr><tr><td>엑셀 표로 컬럼 여러 개를 한 번에 넣기</td><td><a href="/relio/features/dialogs#간편-등록">정보 창 › 간편 등록</a></td></tr><tr><td>큰 모델에서 일부만 보기</td><td><a href="/relio/features/categories">카테고리</a></td></tr><tr><td>큰 모델에서 테이블 빨리 찾기</td><td><a href="/relio/features/find">찾기와 강조</a></td></tr><tr><td>대상 DB 버전 바꾸기</td><td><a href="/relio/features/model#옵션">모델 메뉴 › 옵션</a></td></tr><tr><td>설계 문제를 한 번에 고치기</td><td><a href="/relio/features/check#문제-목록">설계 검사와 추천 › 문제 목록</a></td></tr><tr><td>두 버전의 모델 비교하기</td><td><a href="/relio/features/git#비교-화면">Git과 합치기 › 비교 화면</a></td></tr><tr><td>Git 병합 충돌 풀기</td><td><a href="/relio/features/git#합치기">Git과 합치기 › 합치기</a></td></tr><tr><td>지금 상태를 사본으로 남기고 되돌리기</td><td><a href="/relio/features/model#변경-내역">모델 메뉴 › 변경 내역</a></td></tr><tr><td>쓰지 않는 단어 정리하기</td><td><a href="/relio/features/model#단어-사전·단어-정보">모델 메뉴 › 단어 사전</a></td></tr><tr><td>망가진 파일 열기</td><td><a href="/relio/features/file#고쳐서-열기">파일 › 고쳐서 열기</a></td></tr><tr><td>갑자기 꺼진 뒤 복구하기</td><td><a href="/relio/features/file#자동-백업과-복구">파일 › 자동 백업과 복구</a></td></tr><tr><td>캔버스를 넓게 쓰기</td><td><a href="/relio/features/canvas#패널과-시작-화면">캔버스와 팔레트 › 패널과 시작 화면</a></td></tr><tr><td>단축키 바꾸기</td><td><a href="/relio/features/preferences#단축키">환경 설정 › 단축키</a></td></tr><tr><td>테마·표시 언어 바꾸기</td><td><a href="/relio/features/preferences#화면">환경 설정 › 화면</a></td></tr><tr><td>CI에서 설계 검사·DDL 만들기</td><td><a href="/relio/features/cli#ci에서-쓰기">명령줄 › CI에서 쓰기</a></td></tr><tr><td>새 버전 받기</td><td><a href="/relio/features/update">업데이트</a></td></tr><tr><td>문제 알리기</td><td><a href="/relio/features/troubleshooting#문제-알리기">도움말과 문제 해결 › 문제 알리기</a></td></tr></tbody></table><h2 id="그리기와-편집" tabindex="-1">그리기와 편집 <a class="header-anchor" href="#그리기와-편집" aria-label="Permalink to &quot;그리기와 편집&quot;">​</a></h2><ul><li><a href="/relio/features/file">파일</a> — 새로 만들기·열기·저장·최근 파일·자동 백업·고쳐서 열기처럼 파일 메뉴와 문서 탭에서 하는 일을 다룹니다.</li><li><a href="/relio/features/edit">편집</a> — 잘라내기·복사·붙여넣기, 되돌리기, 검색 창, 모든 속성 편집 등 편집 메뉴의 기능을 다룹니다.</li><li><a href="/relio/features/canvas">캔버스와 팔레트</a> — 캔버스 읽는 법, 팔레트 도구(선택·손·테이블·뷰·관계·노트·카테고리·이미지), 선택·옮기기, 배치 메뉴, 보기 메뉴 설정, 확대·이동, 아웃라인을 다룹니다.</li><li><a href="/relio/features/dialogs">정보 창</a> — 테이블 정보(컬럼·인덱스·복합 고유 키·고급), 컬럼 정보, 간편 등록, 인덱스·뷰·관계 정보, 노트 연결선·이미지 창의 항목을 다룹니다.</li><li><a href="/relio/features/model">모델 메뉴</a> — 단어 사전, 그룹·글로벌 그룹, 시퀀스·트리거·테이블스페이스, 옵션, 변경 내역, 번역 관리, 테스트 데이터, 모델 특성을 다룹니다.</li><li><a href="/relio/features/categories">카테고리</a> — 카테고리 영역 만들기, 카테고리 관리, 하단 카테고리 탭, 여러 카테고리 함께 보기, 참조하는 테이블 보기를 다룹니다.</li><li><a href="/relio/features/find">찾기와 강조</a> — 찾기 막대와 일치 방식, 한글 초성 찾기, 마우스 올림·선택 연결 강조, 강조 설정을 다룹니다.</li><li><a href="/relio/features/check">설계 검사와 추천</a> — 설계 검사 규칙과 표시, 문제 목록에서 고치기·예외, 입력 중 추천, 관계 이름 짝을 다룹니다.</li></ul><h2 id="내보내기와-연동" tabindex="-1">내보내기와 연동 <a class="header-anchor" href="#내보내기와-연동" aria-label="Permalink to &quot;내보내기와 연동&quot;">​</a></h2><ul><li><a href="/relio/features/ddl">DDL</a> — DDL 내보내기 창의 대상 DB·버전, 만들 것, 환경·인코딩·줄바꿈, 버전별 문법 경고를 다룹니다.</li><li><a href="/relio/features/export">내보내기</a> — Excel·HTML·이미지·사전·테스트 데이터·Java·DBML·Mermaid·Markdown·모델 JSON 내보내기와 인쇄를 다룹니다.</li><li><a href="/relio/features/import">가져오기와 다른 형식</a> — SQL·DBML·Mermaid·Markdown에서 가져오기, 다른 .erm 파일에서 가져오기, 가져올 곳과 이름 겹침 처리를 다룹니다.</li><li><a href="/relio/features/database">DB 연동</a> — DB 접속과 연결 목록, DB에서 가져오기, DB로 내보내기, Oracle·ODBC 준비, 암호 저장 방식을 다룹니다.</li><li><a href="/relio/features/git">Git과 합치기</a> — 두 파일 비교와 변경 SQL, Git 이력, 3방향 합치기 화면, Git merge driver를 다룹니다.</li></ul><h2 id="설정과-도움" tabindex="-1">설정과 도움 <a class="header-anchor" href="#설정과-도움" aria-label="Permalink to &quot;설정과 도움&quot;">​</a></h2><ul><li><a href="/relio/features/preferences">환경 설정</a> — 일반(언어·테마·백업·강조·업데이트), 글로벌 그룹, 번역 사전, Excel 템플릿, DB 연결, 설계 검사, 단축키, 암호 설정을 다룹니다.</li><li><a href="/relio/features/cli">명령줄</a> — relio export·import·diff·merge·lint·db 명령과 옵션, 종료 코드, 빌드·CI에서 쓰는 방법을 다룹니다.</li><li><a href="/relio/features/update">업데이트</a> — 새 버전 자동 확인, 업데이트 확인, Relio 안에서 받아 설치하기, 설치 없이 쓰는 실행판의 업데이트를 다룹니다.</li><li><a href="/relio/features/troubleshooting">도움말과 문제 해결</a> — 도움말 메뉴(사용 설명서·새 소식·Relio 정보·오픈소스 라이선스), 파일이 열리지 않을 때, 갑자기 꺼졌을 때, DB 접속 문제, 진단 기록, 문제 알리기, 내 정보가 저장되는 곳을 다룹니다.</li></ul>',13)])])}const g=t(l,[["render",d]]);export{c as __pageData,g as default};
